import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh } = ctx.THREE;

  const group = new Group();
  group.userData.cleanup = () => {
    group.traverse((node) => {
      if (node.isMesh) {
        node.geometry?.dispose();
        node.material?.dispose();
      }
    });
  };

  // Load the sprite texture
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    // Atlas region: 0, 0, 512, 320 (full texture, aspect ratio 512/320 = 1.6)
    const atlasWidth = 512;
    const atlasHeight = 320;
    const atlasAspect = atlasWidth / atlasHeight;

    // Create plane geometry matching atlas aspect ratio
    // Scale to fit the scene composition (~0.8 units wide for a card element)
    const planeWidth = 0.8;
    const planeHeight = planeWidth / atlasAspect;
    const geometry = new PlaneGeometry(planeWidth, planeHeight, 1, 1);

    // Set texture parameters
    texture.magFilter = ctx.THREE.LinearFilter;
    texture.minFilter = ctx.THREE.LinearMipmapLinearFilter;

    // Create material using TSL nodes for UV mapping
    // Atlas region: srcX=0, srcY=0, w=512, h=320 (normalized: 0-1 for full texture)
    const uvNode = uv();
    const material = new MeshBasicNodeMaterial({
      colorNode: texture,
      transparent: true,
      side: ctx.THREE.DoubleSide,
    });

    const mesh = new Mesh(geometry, material);
    mesh.renderOrder = 1; // Ensure sprite renders after backdrop

    group.add(mesh);
  });

  return group;
}
